export function SvgIcon({ path, size = 18, className = "" }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      className={className}
      aria-hidden="true"
    >
      <path d={path} />
    </svg>
  );
}

export const LanguagesCategoryIcon = (props) => <Code size={props.size || 18} className={props.className || ""} />;
export const AIToolingCategoryIcon = (props) => <Brain size={props.size || 18} className={props.className || ""} />;
export const MLCategoryIcon = (props) => <Cpu size={props.size || 18} className={props.className || ""} />;
export const BackendCategoryIcon = (props) => <HardDrives size={props.size || 18} className={props.className || ""} />;
export const DataCategoryIcon = (props) => <Database size={props.size || 18} className={props.className || ""} />;

export const TensorFlowIcon = (props) => <SvgIcon path={SVG_PATHS.tensorflow} {...props} />;

// Dynamic Tech Icon Component
export function TechIcon({ name, size = 14, className = "" }) {
  if (!name) return null;
  const key = String(name).trim().toLowerCase();
  switch (key) {
    case 'python':
    case 'python 3.10':
    case 'python 3.11':
      return <SvgIcon path={SVG_PATHS.python} size={size} className={className} />;
    case 'c':
      return <SvgIcon path={SVG_PATHS.c} size={size} className={className} />;
    case 'c++':
    case 'c/c++':
    case 'c99':
      return <SvgIcon path={SVG_PATHS.cpp} size={size} className={className} />;
    case 'typescript':
      return <SvgIcon path={SVG_PATHS.typescript} size={size} className={className} />;
    case 'bash':
      return <SvgIcon path={SVG_PATHS.bash} size={size} className={className} />;
    case 'sql':
      return <Database size={size} className={className} />;

    case 'agentic ai':
    case 'autonomous agents':
    case 'ai agents':
      return <Robot size={size} className={className} />;
    case 'ai coding':
    case 'ai-based coding':
    case 'agentic coding':
      return <Code size={size} className={className} />;
    case 'connectors':
    case 'plugins':
    case 'connectors & plugins':
    case 'ai connectors':
      return <Plug size={size} className={className} />;
    case 'skills':
    case 'agent skills':
    case 'ai skills':
      return <PuzzlePiece size={size} className={className} />;
    case 'mcp':
    case 'modelcontextprotocol':
    case 'model context protocol':
      return <SvgIcon path={SVG_PATHS.mcp} size={size} className={className} />;
    case 'ai automation':
    case 'automation':
      return <Lightning size={size} className={className} />;
    case 'ollama':
    case 'llms (ollama)':
      return <SvgIcon path={SVG_PATHS.ollama} size={size} className={className} />;
    case 'langchain':
      return <SvgIcon path={SVG_PATHS.langchain} size={size} className={className} />;
    case 'rag pipelines':
      return <MagnifyingGlass size={size} className={className} />;
    case 'vector search':
    case 'vector search (faiss, bm25)':
    case 'faiss + bm25':
      return <Graph size={size} className={className} />;
    case 'cross-encoder reranking':
      return <Sliders size={size} className={className} />;
    case 'sentence-transformers':
    case 'sentence transformers':
      return <Brain size={size} className={className} />;
    case 'hugging face':
    case 'hugging face transformers':
      return <SvgIcon path={SVG_PATHS.huggingface} size={size} className={className} />;
    case 'llama.cpp':
    case 'llamagrammar':
    case 'nemotron':
    case 'nemotron 550b':
      return <Brain size={size} className={className} />;

    case 'pytorch':
      return <SvgIcon path={SVG_PATHS.pytorch} size={size} className={className} />;
    case 'tensorflow':
    case 'tensorflow core':
      return <SvgIcon path={SVG_PATHS.tensorflow} size={size} className={className} />;
    case 'scikit-learn':
      return <SvgIcon path={SVG_PATHS.scikitlearn} size={size} className={className} />;
    case 'opencv':
      return <SvgIcon path={SVG_PATHS.opencv} size={size} className={className} />;
    case 'shap':
    case 'shap (explainable ai)':
      return <ChartBar size={size} className={className} />;
    case 'tesseract':
    case 'tesseract ocr':
    case 'ocr (tesseract)':
      return <FileText size={size} className={className} />;

    case 'fastapi':
      return <SvgIcon path={SVG_PATHS.fastapi} size={size} className={className} />;
    case 'next.js':
    case 'next.js 16':
      return <SvgIcon path={SVG_PATHS.nextdotjs} size={size} className={className} />;
    case 'react':
    case 'react 19':
      return <SvgIcon path={SVG_PATHS.react} size={size} className={className} />;
    case 'redis':
      return <SvgIcon path={SVG_PATHS.redis} size={size} className={className} />;
    case 'sqlite':
    case 'sqlite wal':
      return <SvgIcon path={SVG_PATHS.sqlite} size={size} className={className} />;
    case 'sqlalchemy':
      return <SvgIcon path={SVG_PATHS.sqlalchemy} size={size} className={className} />;
    case 'websockets':
      return <Broadcast size={size} className={className} />;
    case 'platformio':
      return <SvgIcon path={SVG_PATHS.platformio} size={size} className={className} />;
    case 'esp32':
    case 'microcontrollers':
    case 'quantization':
    case 'int8 quantization':
      return <Cpu size={size} className={className} />;
    case 'jwt':
    case 'jwt & rbac':
    case 'jwt & role-based access (rbac)':
      return <SvgIcon path={SVG_PATHS.jwt} size={size} className={className} />;
    case 'rest apis':
      return <Globe size={size} className={className} />;
    case 'uv':
    case 'uvicorn':
      return <Sliders size={size} className={className} />;

    case 'pandas':
      return <SvgIcon path={SVG_PATHS.pandas} size={size} className={className} />;
    case 'numpy':
      return <SvgIcon path={SVG_PATHS.numpy} size={size} className={className} />;
    case 'plotly':
    case 'plotly dash':
      return <SvgIcon path={SVG_PATHS.plotly} size={size} className={className} />;
    case 'docker':
      return <SvgIcon path={SVG_PATHS.docker} size={size} className={className} />;
    case 'git':
      return <SvgIcon path={SVG_PATHS.git} size={size} className={className} />;
    case 'github actions':
      return <SvgIcon path={SVG_PATHS.githubactions} size={size} className={className} />;
    case 'pytest':
      return <SvgIcon path={SVG_PATHS.pytest} size={size} className={className} />;
    case 'linux':
      return <SvgIcon path={SVG_PATHS.linux} size={size} className={className} />;
    case 'etl pipelines':
      return <ArrowsMerge size={size} className={className} />;
    case 'n8n':
      return <SvgIcon path={SVG_PATHS.n8n} size={size} className={className} />;
    default:
      return null;
  }
}

export function TechTag({ name, className = "" }) {
  return (
    <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-full bg-white/5 border border-white/10 text-white/70 hover:border-white/20 hover:text-white transition-colors duration-200 ${className}`}>
      <TechIcon name={name} size={13} className="shrink-0 text-white/60" />
      <span>{name}</span>
    </span>
  );
}
